VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,8.11,"Lecture four. Replication. This is how copies of the data keep a system running, and what can go wrong with them."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":20.016,"caps":[[0.5,5.95,"600 requests a second, on one machine or three."],[6.2,10.13,"The big machine crashes: nothing is served."],[10.38,15.43,"A small one crashes: 400 are still served."],[15.68,18.73,"Scaling out survives failures."]],"warp":[[0,0],[0.5,0.7],[6.2,4],[10.38,7],[15.68,9.8],[20.016,12]]},{"dur":18.343,"caps":[[0.5,4.91,"Replication: every node keeps a full copy."],[5.16,10.61,"Partitioning: each node keeps a piece."],[10.86,17.03,"When a node fails, the copies carry on."]],"warp":[[0,0],[0.5,0.9],[5.16,4.4],[10.86,7.2],[18.343,10.5]]},{"dur":18.414,"caps":[[0.66,6.43,"Every write goes to the leader."],[6.68,12.37,"It sends each change on, in order, as a log."],[12.62,16.87,"Reads can go to any node, writes only to the leader."]],"warp":[[0,0],[0.66,1.2],[6.68,4.8],[12.62,9],[18.414,13]]},{"dur":21.571,"caps":[[0.5,4.03,"The leader stores the write in 5 ms."],[4.28,8.77,"Followers confirm at 35 and 95 ms."],[9.02,14.47,"Answer at once, or wait for the followers."],[14.72,20.65,"If the leader then crashes, only waiting keeps the write."]],"warp":[[0,0],[0.5,0.7],[4.28,3],[9.02,5.9],[14.72,8.9],[21.571,12.5]]},{"dur":20.039,"caps":[[0.5,3.39,"A new follower needs a copy."],[3.64,6.05,"Take a snapshot of the leader."],[6.3,9.51,"Writes keep coming while it copies."],[9.76,14.01,"It asks for every change since."],[14.26,18.51,"Caught up: no pause in writes."]],"warp":[[0,0],[0.5,0.8],[3.64,3],[6.3,4.9],[9.76,7.2],[14.26,9.6],[20.039,12]]},{"dur":24.961,"caps":[[0.5,5.15,"The leader wrote 20 changes; followers lag."],[5.4,9.01,"The leader crashes. Which follower takes over?"],[9.26,16.07,"Best: the most up-to-date follower."],[16.32,19.53,"B takes over."],[19.78,23.71,"The 2 changes no follower had are lost."]],"warp":[[0,0],[0.5,0.8],[5.4,3.6],[9.26,6.5],[16.32,8.7],[19.78,10.1],[24.961,13]]},{"dur":28.329,"caps":[[0.5,2.67,"A is the leader."],[2.92,8.45,"A is cut off; B and C think it died."],[8.7,14.71,"B is promoted, yet A still leads."],[14.96,20.97,"Both take a write for seat 12."],[21.22,26.51,"Split brain: two histories disagree."]],"warp":[[0,0],[0.5,0.5],[2.92,2.2],[8.7,4.4],[14.96,6.5],[21.22,8.9],[28.329,11.5]]},{"dur":16.672,"caps":[[0.72,3.76,"You post a comment to the leader."],[4.01,8.43,"Reload: a follower that lags still shows 3."],[8.68,11.17,"Your comment seems to be gone."],[11.42,15.03,"Fix: read your own recent posts from the leader."]],"warp":[[0,0],[0.715,1.3],[4.015,3.9],[8.675,6.7],[11.415,8.8],[16.672,12.5]]},{"dur":18.436,"caps":[[0.72,4.72,"Refresh: replica A says 7."],[4.97,10.43,"B says 6: time ran backwards."],[10.68,14.21,"Fix: keep each user on one replica."],[14.46,17.11,"Their view only moves forward."]],"warp":[[0,0],[0.715,1.3],[4.975,3.1],[10.675,5.6],[14.455,9.5],[18.436,11.5]]},{"dur":18.228,"caps":[],"warp":[[0,0],[0.5,0.9],[7,2],[10.62,3.1],[18.228,9]]}]};
